 36→func (d *Droid) IsTransientError(out Output, err error) bool {
 37→	if err == nil {
 38→		return false
 39→	}
 40→	combined := out.Stdout + out.Stderr
 41→	transientPatterns := []string{
 42→		"overloaded",
 43→		"rate limit",
 44→		"529",
 45→		"503",
 46→		"ECONNRESET",
 47→		"ETIMEDOUT",
 48→	}
 49→	for _, p := range transientPatterns {
 50→		if strings.Contains(combined, p) {
 51→			return true
 52→		}
 53→	}
 54→	return false
 55→}
