 80→const (
 81→	// Droid v0.63+ expects custom model selection using custom:<model-id>.
 82→	// The displayName in settings is not accepted by --model.
 83→	droidCustomModelDisplayName = "claude-haiku-custom"
 84→	droidCustomModelBaseID      = "claude-haiku-4-5-20251001"
 85→	defaultDroidModel           = "custom:" + droidCustomModelBaseID
