 11→// TmuxSession implements Session using tmux for PTY-based interactive agents.
 12→type TmuxSession struct {
 13→	name         string
 14→	stableAtSend string   // stable content snapshot when Send was last called
 15→	cleanups     []func() // run on Close
 16→}
 17→
 18→// OnClose registers a function to run when the session is closed.
 19→func (s *TmuxSession) OnClose(fn func()) {
 20→	s.cleanups = append(s.cleanups, fn)
 21→}
 22→
 23→// NewTmuxSession creates a new tmux session running the given command in dir.
 24→// unsetEnv lists environment variable names to strip from the session.
 25→func NewTmuxSession(name string, dir string, unsetEnv []string, command string, args ...string) (*TmuxSession, error) {
 26→	s := &TmuxSession{name: name}
 27→
 28→	tmuxArgs := []string{"new-session", "-d", "-s", name, "-c", dir}
 29→	// Build a shell command string, prefixed with env -u for each var to strip.
 30→	// All arguments are shell-quoted to prevent injection or splitting.
 31→	var parts []string
 32→	for _, v := range unsetEnv {
 33→		parts = append(parts, "env", "-u", shellQuote(v))
 34→	}
 35→	parts = append(parts, shellQuote(command))
 36→	for _, a := range args {
 37→		parts = append(parts, shellQuote(a))
 38→	}
 39→	tmuxArgs = append(tmuxArgs, strings.Join(parts, " "))
 40→
 41→	cmd := exec.Command("tmux", tmuxArgs...)
 42→	if out, err := cmd.CombinedOutput(); err != nil {
 43→		return nil, fmt.Errorf("tmux new-session: %w\n%s", err, out)
 44→	}
 45→	// Keep the pane around after the command exits so we can capture error output.
 46→	setCmd := exec.Command("tmux", "set-option", "-t", name, "remain-on-exit", "on")
 47→	_ = setCmd.Run()
 48→	return s, nil
 49→}
 50→
 51→func (s *TmuxSession) Send(input string) error {
 52→	preSend := stableContent(s.Capture())
 53→	// Send text and Enter separately — Claude's TUI can swallow Enter
 54→	// if it arrives before the input handler finishes processing the text.
 55→	if err := s.SendKeys(input); err != nil {
 56→		return err
 57→	}
 58→	time.Sleep(200 * time.Millisecond)
 59→	if err := s.SendKeys("Enter"); err != nil {
 60→		return err
 61→	}
 62→
 63→	// Wait for the terminal to reflect the echoed input, then snapshot.
 64→	// This ensures WaitFor compares against post-echo content, preventing
 65→	// false matches on prompt characters (e.g. ❯) in the echoed input.
 66→	deadline := time.Now().Add(5 * time.Second)
 67→	for time.Now().Before(deadline) {
 68→		time.Sleep(200 * time.Millisecond)
 69→		current := stableContent(s.Capture())
 70→		if current != preSend {
 71→			s.stableAtSend = current
 72→			return nil
 73→		}
 74→	}
 75→	s.stableAtSend = stableContent(s.Capture())
 76→	return nil
 77→}
 78→
 79→// SendKeys sends raw tmux key names without appending Enter.
 80→func (s *TmuxSession) SendKeys(keys ...string) error {
 81→	args := append([]string{"send-keys", "-t", s.name}, keys...)
 82→	cmd := exec.Command("tmux", args...)
 83→	out, err := cmd.CombinedOutput()
 84→	if err != nil {
 85→		return fmt.Errorf("tmux send-keys: %w\n%s", err, out)
 86→	}
 87→	return nil
 88→}
