105→func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
106→	re, err := regexp.Compile(pattern)
107→	if err != nil {
108→		return "", fmt.Errorf("invalid pattern: %w", err)
109→	}
110→
111→	deadline := time.Now().Add(timeout)
112→	var matchedAt time.Time
113→	var lastStable string
114→	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
115→
116→	for time.Now().Before(deadline) {
117→		content := s.Capture()
118→		stable := stableContent(content)
119→
120→		if !re.MatchString(content) {
121→			// Pattern lost — reset
122→			matchedAt = time.Time{}
123→			lastStable = ""
124→			time.Sleep(pollInterval)
125→			continue
126→		}
127→
128→		// Detect content change since Send was called
129→		if !contentChanged && stable != s.stableAtSend {
130→			contentChanged = true
131→		}
132→
133→		if stable != lastStable {
134→			// Pattern matches but content is still changing — reset settle timer
135→			matchedAt = time.Now()
136→			lastStable = stable
137→			time.Sleep(pollInterval)
138→			continue
139→		}
140→
141→		// Pattern matches and content hasn't changed since matchedAt.
142→		// Only settle if content changed at least once after Send
143→		// (prevents false settle on echoed input before agent starts).
144→		if contentChanged && time.Since(matchedAt) >= settleTime {
145→			return content, nil
146→		}
147→
148→		time.Sleep(pollInterval)
149→	}
150→	content := s.Capture()
151→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
152→}
