160→func (s *TmuxSession) Close() error {
161→	for _, fn := range s.cleanups {
162→		fn()
163→	}
164→	cmd := exec.Command("tmux", "kill-session", "-t", s.name)
165→	out, err := cmd.CombinedOutput()
166→	if err != nil {
167→		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
168→	}
169→	return nil
170→}
