375→// Send sends input to an interactive session and logs it to ConsoleLog.
376→// Fails the test on error.
377→func (s *RepoState) Send(t *testing.T, session agents.Session, input string) {
378→	t.Helper()
379→	s.ConsoleLog.WriteString("> send: " + input + "\n")
380→	if err := session.Send(input); err != nil {
381→		t.Fatalf("send failed: %v", err)
382→	}
383→}
